<?php
 namespace Pterodactyl\Http\Controllers\Api\Client\Dezerx; use Illuminate\Http\Request; use Pterodactyl\Models\User; use Pterodactyl\Models\ApiKey; use Illuminate\Http\JsonResponse; use Pterodactyl\Facades\Activity; use Pterodactyl\Models\Dezerx\DiscordBot; use Pterodactyl\Models\Dezerx\DiscordLink; use Pterodactyl\Models\Dezerx\DiscordBotAlert; use Pterodactyl\Models\Dezerx\DiscordBotMember; use Pterodactyl\Services\Dezerx\DiscordBot\Art; use Pterodactyl\Services\Dezerx\DiscordBot\Linker; use Pterodactyl\Services\Dezerx\DiscordBot\Preview; use Pterodactyl\Services\Dezerx\DiscordBot\Servers; use Pterodactyl\Services\Dezerx\DiscordBot\Commands; use Pterodactyl\Services\Dezerx\DiscordBot\BotConfig; use Pterodactyl\Services\Dezerx\DiscordBot\BotSettings; use Pterodactyl\Services\Dezerx\DiscordBot\DiscordRest; use Pterodactyl\Http\Controllers\Api\Client\ClientApiController; use Symfony\Component\HttpKernel\Exception\NotFoundHttpException; class DiscordBotController extends ClientApiController { public function __construct(private Linker $linker, private DiscordRest $rest) { parent::__construct(); } public function index(Request $request): JsonResponse { $this->assertEnabled(); return new JsonResponse($this->state($request->user())); } public function link(Request $request): JsonResponse { $this->assertEnabled(); if (BotConfig::personal()) { return $this->fail('This panel runs a bot per person, so there is no shared bot to link to.'); } $user = $request->user(); $existing = DiscordLink::query()->where('user_id', $user->id)->first(); if ($existing === null) { return $this->fail('There is no verified Discord account on file for you yet. Use Connect Discord instead.'); } $result = $this->linker->link($user, [ 'id' => $existing->discord_id, 'username' => $existing->username, 'avatar' => $existing->avatar, ]); if (!$result['ok']) { return $this->fail($result['message']); } Activity::event('user:discord-bot.link')->property('discord', $existing->username)->log(); return new JsonResponse($this->state($user)); } public function key(Request $request): JsonResponse { $this->assertEnabled(); $member = $this->member($request->user()); $this->linker->reissue($member); return new JsonResponse($this->state($request->user())); } public function unlink(Request $request): JsonResponse { $this->assertEnabled(); $this->linker->unlink($this->member($request->user())); Activity::event('user:discord-bot.unlink')->log(); return new JsonResponse($this->state($request->user())); } public function saveBot(Request $request): JsonResponse { $this->assertEnabled(); if (!BotConfig::personal()) { return $this->fail('This panel runs one bot for everybody, so there is nothing to set up here.'); } $data = $request->validate(['token' => ['required', 'string', 'min:50', 'max:120']]); $token = (string) preg_replace('/^Bot\s+/i', '', trim($data['token'])); $application = $this->rest->application($token); if ($application === null || $application['public_key'] === '') { return $this->fail('Discord did not accept that token. Copy it again from the Bot page of your application, and make sure it is the bot token rather than the client secret.'); } $user = $request->user(); $taken = DiscordBot::query() ->where('application_id', $application['id']) ->where(fn ($query) => $query->whereNull('user_id')->orWhere('user_id', '!=', $user->id)) ->exists(); if ($taken) { return $this->fail('That application is already connected to this panel by somebody else.'); } $bot = BotConfig::personalBot($user->id) ?? new DiscordBot(['user_id' => $user->id]); if ($bot->exists && $bot->application_id !== $application['id']) { $bot->commands_hash = null; } $bot->fill([ 'application_id' => $application['id'], 'public_key' => $application['public_key'], 'token' => $token, 'owner_ids' => $application['owner_ids'], 'name' => mb_substr($application['name'], 0, 191), 'avatar' => $application['icon'], ])->save(); $this->linker->keyForBot($bot->load('owner')); $sync = $this->rest->syncCommands($bot, true); Activity::event('user:discord-bot.personal')->property('application', $application['name'])->log(); return new JsonResponse($this->state($user) + ['sync' => $sync]); } public function saveSettings(Request $request): JsonResponse { $this->assertEnabled(); $bot = $this->ownBot($request->user()); $data = $request->validate([ 'design' => ['sometimes', 'array'], 'commands' => ['sometimes', 'array'], 'users' => ['sometimes', 'array', 'max:' . BotSettings::MAX_USERS], 'users.*' => ['string', 'regex:/^\d{17,20}$/'], ]); $users = null; if (array_key_exists('users', $data)) { $users = $this->resolveUsers($bot, $data['users']); if (is_string($users)) { return $this->fail($users); } } BotSettings::save($bot, $data['design'] ?? null, $data['commands'] ?? null, $users); $sync = $this->rest->syncCommands($bot->refresh()); return new JsonResponse($this->state($request->user()) + ['sync' => $sync]); } public function hidden(Request $request): JsonResponse { $this->assertEnabled(); $data = $request->validate([ 'hidden' => ['present', 'array', 'max:' . Servers::MAX_LISTED], 'hidden.*' => ['string', 'uuid'], ]); $user = $request->user(); $reachable = $user->accessibleServers()->pluck('servers.uuid')->all(); $hidden = array_values(array_intersect(array_unique($data['hidden']), $reachable)); $user->forceFill([ 'dezerx_preferences' => [...($user->dezerx_preferences ?? []), Servers::PREFERENCE => $hidden], ])->saveOrFail(); return new JsonResponse($this->state($user->refresh())); } public function roles(Request $request): JsonResponse { $this->assertEnabled(); $bot = $this->ownBot($request->user()); $guilds = $this->rest->guilds($bot); if ($guilds === null) { return $this->fail('Discord would not list the servers this bot is in.'); } $out = []; foreach (array_slice($guilds, 0, 10) as $guild) { $out[] = $guild + ['roles' => $this->rest->roles($bot, $guild['id']) ?? []]; } return new JsonResponse(['guilds' => $out]); } public function preview(Request $request): JsonResponse { $this->assertEnabled(); $user = $request->user(); $bot = BotConfig::personal() ? BotConfig::personalBot($user->id) : BotConfig::globalBot(); $data = $request->validate([ 'design' => ['sometimes', 'array'], 'commands' => ['sometimes', 'array'], ]); $own = $bot !== null && !$bot->isGlobal(); return new JsonResponse([ 'css' => Preview::css(), 'previews' => Preview::gallery( $bot ?? new DiscordBot(['user_id' => $user->id, 'name' => 'Your bot', 'application_id' => '0']), $own ? ($data['design'] ?? null) : null, $own ? ($data['commands'] ?? null) : null, ), ]); } public function syncBot(Request $request): JsonResponse { $this->assertEnabled(); $bot = $this->ownBot($request->user()); $this->linker->keyForBot($bot); $sync = $this->rest->syncCommands($bot, true); return new JsonResponse($this->state($request->user()) + ['sync' => $sync]); } public function deleteBot(Request $request): JsonResponse { $this->assertEnabled(); $bot = BotConfig::personalBot($request->user()->id); if ($bot !== null) { $this->linker->forgetBot($bot); Activity::event('user:discord-bot.personal-removed')->log(); } return new JsonResponse($this->state($request->user())); } public function deleteAlert(Request $request, int $alert): JsonResponse { $this->assertEnabled(); DiscordBotAlert::query()->where('user_id', $request->user()->id)->whereKey($alert)->delete(); return new JsonResponse($this->state($request->user())); } private function state(User $user): array { $settings = BotConfig::all(); $personal = BotConfig::personal(); $member = DiscordBotMember::query()->where('user_id', $user->id)->first(); $bot = $personal ? BotConfig::personalBot($user->id) : BotConfig::globalBot(); $suggested = !$personal && $member === null ? DiscordLink::query()->where('user_id', $user->id)->first() : null; $memberKey = $member?->api_key_id === null ? null : ApiKey::query()->find($member->api_key_id); $botKey = $bot === null || $bot->isGlobal() || $bot->api_key_id === null ? null : ApiKey::query()->find($bot->api_key_id); $alerts = DiscordBotAlert::query() ->with('server') ->where('user_id', $user->id) ->orderBy('id') ->get() ->map(fn (DiscordBotAlert $alert) => [ 'id' => $alert->id, 'server' => ['name' => $alert->server?->name ?? 'Server', 'identifier' => $alert->server?->uuidShort], 'channelUrl' => 'https://discord.com/channels/' . $alert->guild_id . '/' . $alert->channel_id, 'roleId' => $alert->role_id, 'cpu' => $alert->cpu, 'memory' => $alert->memory, 'disk' => $alert->disk, 'offline' => $alert->offline, 'cooldown' => $alert->cooldown, 'notifiedAt' => $alert->notified_at?->toAtomString(), 'lastError' => $alert->last_error, ]) ->all(); return [ 'enabled' => BotConfig::enabled(), 'mode' => $settings['mode'], 'alerts' => $settings['alerts'], 'billing' => BotConfig::billingEnabled(), 'consoleImages' => $settings['console_images'], 'oauth' => [ 'available' => !$personal && $bot !== null && $bot->canOAuth(), 'connectUrl' => route('dezerx.discordbot.connect'), ], 'bot' => $bot === null ? null : [ 'name' => $bot->name, 'avatar' => $bot->avatarUrl(), 'applicationId' => $bot->application_id, 'personal' => !$bot->isGlobal(), 'inviteUrl' => BotConfig::inviteUrl($bot), 'userInstallUrl' => $settings['user_install'] ? BotConfig::userInstallUrl($bot) : null, 'endpointUrl' => $bot->isGlobal() ? null : BotConfig::interactionsUrl($bot), 'portalUrl' => $bot->isGlobal() ? null : BotConfig::portalUrl($bot), 'syncedAt' => $bot->commands_synced_at?->toAtomString(), 'syncError' => $bot->isGlobal() ? null : $bot->commands_error, 'upToDate' => $bot->commands_hash === Commands::hash(Commands::definitions($bot)), 'owners' => $bot->isGlobal() ? [] : array_values((array) ($bot->owner_ids ?? [])), 'users' => $bot->isGlobal() ? [] : BotSettings::users($bot), 'keyActive' => $bot->isGlobal() ? null : $botKey !== null, 'design' => BotSettings::design($bot), ], 'commands' => $bot === null ? [] : array_values(array_filter(BotSettings::commands($bot), fn (array $command) => $command['available'] && ($personal || $command['enabled']))), 'member' => $member === null ? null : [ 'discordId' => $member->discord_id, 'username' => $member->username, 'avatar' => $member->avatarUrl(), 'linkedAt' => $member->created_at?->toAtomString(), 'keyActive' => $memberKey !== null, 'keyIdentifier' => $memberKey?->identifier, 'keyLastUsedAt' => $memberKey?->last_used_at?->toAtomString(), ], 'suggested' => $suggested === null ? null : ['username' => $suggested->username, 'avatar' => $suggested->avatarUrl()], 'defaults' => BotSettings::DESIGN, 'bars' => BotSettings::BARS, 'alertList' => $alerts, 'servers' => $this->servers($user), ]; } private function servers(User $user): array { $hidden = Servers::hidden($user); return Servers::reachable($user) ->map(fn ($server) => [ 'uuid' => $server->uuid, 'identifier' => $server->uuidShort, 'name' => $server->name, 'egg' => $server->egg?->name, 'logo' => Art::logo($server->egg?->uuid, $server->egg?->name), 'hidden' => in_array($server->uuid, $hidden, true), ]) ->values() ->all(); } private function ownBot(User $user): DiscordBot { $bot = BotConfig::personal() ? BotConfig::personalBot($user->id) : null; if ($bot === null) { throw new NotFoundHttpException(); } return $bot; } private function member(User $user): DiscordBotMember { $member = DiscordBotMember::query()->with('user')->where('user_id', $user->id)->first(); if ($member === null) { throw new NotFoundHttpException('This account is not linked to Discord.'); } return $member; } private function resolveUsers(DiscordBot $bot, array $ids): array|string { $known = []; foreach (BotSettings::users($bot) as $user) { $known[$user['id']] = $user; } $owners = array_map('strval', (array) ($bot->owner_ids ?? [])); $out = []; foreach (array_values(array_unique(array_map('strval', $ids))) as $id) { if (in_array($id, $owners, true)) { continue; } if (isset($known[$id])) { $out[] = $known[$id]; continue; } $user = $this->rest->user($bot, $id); if ($user === null) { return 'Discord could not be reached to check that user ID. Try again in a moment.'; } if ($user === []) { return "Discord has no account with the ID {$id}."; } $out[] = $user; } return $out; } private function assertEnabled(): void { if (!BotConfig::enabled()) { throw new NotFoundHttpException(); } } private function fail(string $message): JsonResponse { return new JsonResponse(['errors' => [['code' => 'DiscordBot', 'status' => '422', 'detail' => $message]]], 422); } } 